-- The schema is applied by CI migrations; the local runner wraps it in a rollback.
begin;
create extension if not exists pgtap with schema extensions;
-- Exercise the final confirmation RPC when present; retain baseline replay for
-- the historical three-migration fixtures used by the concurrency harness.
create function pg_temp.change_plan(p_data jsonb) returns jsonb language plpgsql as $$
begin
 if to_regprocedure('public.confirm_unit_contract_plan_pilot(jsonb)') is not null then
  return public.confirm_unit_contract_plan_pilot(p_data||jsonb_build_object('expectedCatalog',public.proration_catalog_preview_pilot(p_data->>'nextPlanId')));
 end if;
 return public.change_unit_contract_plan_pilot(p_data);
end $$;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('ad000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','proration@example.invalid',now(),now(),now());
insert into public.platform_operators(user_id,role,full_name,email) values('ad000000-0000-4000-8000-000000000001','owner','Proration synthetic','proration@example.invalid');
insert into public.organizations(id,name,slug) values('bd000000-0000-4000-8000-000000000001','Proration synthetic','proration-synthetic');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cd000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001','Sede','sede','headquarters');
insert into public.saas_plans(id,code,name,base_price_cents) values('qa-proration-a','qa-proration-a','Plan A',10000),('qa-proration-b','qa-proration-b','Plan B',16000);
insert into public.saas_subscriptions(organization_id,plan_id,status) values('bd000000-0000-4000-8000-000000000001','qa-proration-a','active') on conflict(organization_id) do update set status='active';
insert into public.saas_unit_contracts(id,organization_id,unit_id,payer_unit_id,plan_id,status) values('dd000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001','cd000000-0000-4000-8000-000000000001','cd000000-0000-4000-8000-000000000001','qa-proration-a','active');
insert into public.saas_invoices(id,church_id,unit_contract_id,unit_id,payer_unit_id,reference_month,due_at,amount_cents,payer_church_id,created_at,updated_at) values('ed000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001','dd000000-0000-4000-8000-000000000001','cd000000-0000-4000-8000-000000000001','cd000000-0000-4000-8000-000000000001','2026-10',0,10000,'bd000000-0000-4000-8000-000000000001',0,0);
select set_config('qa.proration.input',jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000001','contractId','dd000000-0000-4000-8000-000000000001','nextPlanId','qa-proration-b','baseInvoiceId','ed000000-0000-4000-8000-000000000001','expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001'),'cycleStart',floor(extract(epoch from now())*1000)::bigint-1296000000,'cycleEnd',floor(extract(epoch from now())*1000)::bigint+1296000000)::text,true);
select ok(not has_table_privilege('authenticated','public.saas_plan_adjustments','INSERT'),'client cannot fabricate adjustment');
select ok(not has_table_privilege('authenticated','public.saas_plan_adjustments','UPDATE'),'client cannot rewrite adjustment');
select ok(not has_function_privilege('anon','public.change_unit_contract_plan_pilot(jsonb)','EXECUTE'),'visitor cannot change plan');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ad000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb)$$,'42501',null,'manager without MFA refused');
select set_config('request.jwt.claims','{"sub":"ad000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb)$$,'change is atomic');
select is((select plan_id from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001'),'qa-proration-b','plan takes effect immediately');
select is((select adjustment_cents from public.saas_plan_adjustments where request_id='fd000000-0000-4000-8000-000000000001'),3000::bigint,'upgrade proportional cents');
select lives_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb)$$,'same request resumes original snapshot');
select is((select count(*) from public.saas_plan_adjustments),1::bigint,'retry never duplicates adjustment');
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb||'{"nextPlanId":"qa-proration-a"}')$$,'22023',null,'same ID cannot change content');
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb||'{"requestId":"fd000000-0000-4000-8000-000000000002"}')$$,'40001',null,'stale contract version refused');
select is((select amount_cents from public.saas_invoices where id='ed000000-0000-4000-8000-000000000001'),10000::bigint,'old invoice never rewritten');
select set_config('qa.proration.down',(current_setting('qa.proration.input')::jsonb||jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000003','nextPlanId','qa-proration-a','expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001')))::text,true);
select lives_ok($$select pg_temp.change_plan(current_setting('qa.proration.down')::jsonb)$$,'downgrade records credit');
select is((select snapshot->>'creditDestination' from public.saas_plan_adjustments where request_id='fd000000-0000-4000-8000-000000000003'),'next_invoice','credit assigned to next invoice');
select is((select snapshot->>'automaticRefund' from public.saas_plan_adjustments where request_id='fd000000-0000-4000-8000-000000000003'),'false','no automatic refund');
select ok((select adjustment_cents<0 from public.saas_plan_adjustments where request_id='fd000000-0000-4000-8000-000000000003'),'downgrade produces negative adjustment');
select is((select rounded_adjustment from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000001'),0::bigint,'cumulative rounding cancels symmetric changes without extra penny');
select is((select count(*) from public.platform_audit_events where action='unit_contract.plan_changed_pilot' and entity_id='dd000000-0000-4000-8000-000000000001'),2::bigint,'one audit per actual change, never per retry');
select is((select snapshot->'nextPlanSnapshot'->>'base_price_cents' from public.saas_plan_adjustments where request_id='fd000000-0000-4000-8000-000000000001'),'16000','historical price captured');
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.down')::jsonb||jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000004','expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001'),'cycleEnd',0))$$,'22023',null,'invalid cycle refused without mutation');
select is((select count(*) from public.saas_plan_adjustments),2::bigint,'invalid cycle leaves no adjustment');
select is((select count(*) from public.saas_proration_documents where kind='additional_invoice'),1::bigint,'upgrade creates one internal additional invoice document');
select is((select count(*) from public.saas_proration_documents where kind='credit'),1::bigint,'downgrade creates one credit document');
select ok(not has_table_privilege('authenticated','public.saas_proration_credit_uses','INSERT'),'client cannot fabricate credit consumption');
select set_config('qa.proration.issue',jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000005','contractId','dd000000-0000-4000-8000-000000000001','referenceMonth',(select to_char(to_timestamp(cycle_end/1000.0) at time zone 'America/Sao_Paulo','YYYY-MM') from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000001'))::text,true);
reset role;
create function pg_temp.fail_proration_audit() returns trigger language plpgsql as $$begin if new.action='unit_contract.invoice_issued_pilot' then raise exception 'qa_forced_failure';end if;return new;end$$;
create trigger qa_fail_proration_audit before insert on public.platform_audit_events for each row execute function pg_temp.fail_proration_audit();
set local role authenticated;
select throws_ok($$select public.issue_proration_cycle_invoice_pilot(current_setting('qa.proration.issue')::jsonb)$$,'P0001','qa_forced_failure','audit failure rolls back complete issuance');
select is((select count(*) from public.saas_proration_credit_uses),0::bigint,'failed issue does not consume credit');
select is((select count(*) from public.saas_proration_invoice_runs),0::bigint,'failed issue leaves no idempotency record');
select is((select count(*) from public.saas_invoices where unit_contract_id='dd000000-0000-4000-8000-000000000001'),1::bigint,'failed issue leaves only original invoice');
reset role;
drop trigger qa_fail_proration_audit on public.platform_audit_events;
set local role authenticated;
select lives_ok($$select public.issue_proration_cycle_invoice_pilot(current_setting('qa.proration.issue')::jsonb)$$,'next invoice consumes credit atomically');
select is((select snapshot->>'creditAppliedCents' from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000005'),'3000','exact proportional credit consumed');
select is((select snapshot->>'amountCents' from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000005'),'7000','new invoice has net amount after credit');
select lives_ok($$select public.issue_proration_cycle_invoice_pilot(current_setting('qa.proration.issue')::jsonb)$$,'same invoice request resumes original result');
select is((select count(*) from public.saas_proration_credit_uses),1::bigint,'replay never spends credit twice');
select throws_ok($$select public.issue_proration_cycle_invoice_pilot(current_setting('qa.proration.issue')::jsonb||'{"requestId":"fd000000-0000-4000-8000-000000000006"}')$$,'22023',null,'new request cannot issue same period twice');
select is((select amount_cents from public.saas_invoices where id='ed000000-0000-4000-8000-000000000001'),10000::bigint,'original invoice still unchanged after credit use');
select throws_ok($$update public.saas_invoices set status='cancelled' where id=(select invoice_id from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000005')$$,'42501',null,'cannot silently cancel issued invoice and lose consumed credit');
select throws_ok($$update public.saas_invoices set amount_cents=1 where id=(select invoice_id from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000005')$$,'42501',null,'issued amount cannot be rewritten');
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.down')::jsonb||jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000007','nextPlanId','qa-proration-b','expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001')))$$,'40001',null,'preissued future invoice blocks price-changing plan mutation');
select is((select count(*) from public.saas_plan_adjustments),2::bigint,'blocked mutation leaves no adjustment or document');
-- BEGIN ROLLOVER FIXTURE
reset role;
insert into public.saas_plans(id,code,name,base_price_cents) values('qa-proration-c','qa-proration-c','Carry credit plan',1000);
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cd000000-0000-4000-8000-000000000002','bd000000-0000-4000-8000-000000000001','Filha sintética','carry','congregation');
insert into public.saas_unit_contracts(id,organization_id,unit_id,payer_unit_id,plan_id,status) values('dd000000-0000-4000-8000-000000000002','bd000000-0000-4000-8000-000000000001','cd000000-0000-4000-8000-000000000002','cd000000-0000-4000-8000-000000000002','qa-proration-c','active');
insert into public.saas_invoices(id,church_id,unit_contract_id,unit_id,payer_unit_id,reference_month,due_at,amount_cents,payer_church_id,created_at,updated_at) select 'ed000000-0000-4000-8000-000000000002','bd000000-0000-4000-8000-000000000001','dd000000-0000-4000-8000-000000000002','cd000000-0000-4000-8000-000000000002','cd000000-0000-4000-8000-000000000002',to_char((now()-interval '2 months') at time zone 'America/Sao_Paulo','YYYY-MM'),0,4000,'bd000000-0000-4000-8000-000000000001',0,0;
insert into public.saas_proration_cycles(contract_id,invoice_id,cycle_start,cycle_end,net_cents,accumulated_numerator,rounded_adjustment,contract_updated_at) select id,'ed000000-0000-4000-8000-000000000002',floor(extract(epoch from now()-interval '31 days')*1000)::bigint,floor(extract(epoch from now()-interval '1 day')*1000)::bigint,1000,-1500::numeric*2592000000,-1500,updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000002';
insert into public.saas_invoices(id,church_id,unit_contract_id,unit_id,payer_unit_id,reference_month,due_at,amount_cents,payer_church_id,created_at,updated_at) select 'ed000000-0000-4000-8000-000000000003','bd000000-0000-4000-8000-000000000001',contract_id,'cd000000-0000-4000-8000-000000000002','cd000000-0000-4000-8000-000000000002',to_char(to_timestamp(cycle_end/1000.0) at time zone 'America/Sao_Paulo','YYYY-MM'),cycle_end,1000,'bd000000-0000-4000-8000-000000000001',0,0 from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000002';
insert into public.saas_proration_invoice_runs(request_id,contract_id,invoice_id,reference_month,fingerprint,snapshot) select 'fd000000-0000-4000-8000-000000000020',unit_contract_id,id,reference_month,'{}',jsonb_build_object('grossCents','1000') from public.saas_invoices where id='ed000000-0000-4000-8000-000000000003';
insert into public.saas_plan_adjustments(request_id,contract_id,actor_id,fingerprint,snapshot,adjustment_cents) select 'fd000000-0000-4000-8000-000000000022',contract_id,'ad000000-0000-4000-8000-000000000001','{}',jsonb_build_object('payerUnitId','cd000000-0000-4000-8000-000000000002','cycleEnd',cycle_end),-1500 from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000002';
-- END ROLLOVER FIXTURE
select is(to_timestamp(private.proration_next_boundary((extract(epoch from '2028-01-31T03:00:00Z'::timestamptz)*1000)::bigint,31)/1000.0) at time zone 'America/Sao_Paulo','2028-02-29 00:00:00'::timestamp,'leap February clips anchored day');
select is(to_timestamp(private.proration_next_boundary((extract(epoch from '2028-02-29T03:00:00Z'::timestamptz)*1000)::bigint,31)/1000.0) at time zone 'America/Sao_Paulo','2028-03-31 00:00:00'::timestamp,'anchor returns to day 31 after February');
set local role authenticated;
select set_config('qa.proration.roll',jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000021','contractId','dd000000-0000-4000-8000-000000000002','invoiceId','ed000000-0000-4000-8000-000000000003','expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000002'))::text,true);
select throws_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb||'{"invoiceId":"ed000000-0000-4000-8000-000000000002"}')$$,'22023',null,'base invoice cannot stand in for verified new period');
select throws_ok($$select public.rollover_proration_cycle_pilot(jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000025','contractId','dd000000-0000-4000-8000-000000000001','invoiceId',(select invoice_id from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000005'),'expectedUpdatedAt',(select updated_at from public.saas_unit_contracts where id='dd000000-0000-4000-8000-000000000001')))$$,'22023',null,'future period cannot advance early');
reset role;
create or replace function pg_temp.fail_proration_audit() returns trigger language plpgsql as $$begin if new.action='unit_contract.cycle_rolled_pilot' then raise exception 'qa_forced_rollover_failure';end if;return new;end$$;
create trigger qa_fail_proration_audit before insert on public.platform_audit_events for each row execute function pg_temp.fail_proration_audit();
set local role authenticated;
select throws_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb)$$,'P0001','qa_forced_rollover_failure','failed rollover audit rolls back all changes');
select is((select count(*) from public.saas_proration_rollovers),0::bigint,'failed rollover leaves no transition');
select is((select rounded_adjustment from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000002'),-1500::bigint,'failed rollover preserves previous accumulator');
reset role;
drop trigger qa_fail_proration_audit on public.platform_audit_events;
set local role authenticated;
select lives_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb)$$,'elapsed cycle advances atomically');
select is((select rounded_adjustment from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000002'),0::bigint,'new cycle resets rounding accumulator only');
select is((select count(*) from public.saas_proration_documents where contract_id='dd000000-0000-4000-8000-000000000002'),1::bigint,'rollover preserves unconsumed credit');
select lives_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb)$$,'same rollover request returns same transition');
select is((select count(*) from public.saas_proration_rollovers),1::bigint,'rollover replay never advances twice');
select throws_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb||'{"requestId":"fd000000-0000-4000-8000-000000000023"}')$$,'40001',null,'stale version cannot advance again');
select lives_ok($$select public.issue_proration_cycle_invoice_pilot(jsonb_build_object('requestId','fd000000-0000-4000-8000-000000000024','contractId','dd000000-0000-4000-8000-000000000002','referenceMonth',(select to_char(to_timestamp(cycle_end/1000.0) at time zone 'America/Sao_Paulo','YYYY-MM') from public.saas_proration_cycles where contract_id='dd000000-0000-4000-8000-000000000002')))$$,'carried credit applies to next new invoice');
select is((select snapshot->>'amountCents' from public.saas_proration_invoice_runs where request_id='fd000000-0000-4000-8000-000000000024'),'0','credit larger than monthly price produces zero invoice');
select is((select d.amount_cents-coalesce(sum(u.amount_cents),0) from public.saas_proration_documents d left join public.saas_proration_credit_uses u on u.document_id=d.id where d.contract_id='dd000000-0000-4000-8000-000000000002' group by d.id),500::numeric,'unused remainder stays available');
select set_config('request.jwt.claims','{"sub":"ad000000-0000-4000-8000-000000000099","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select pg_temp.change_plan(current_setting('qa.proration.input')::jsonb)$$,'42501',null,'account without operator access cannot replay successful request');
select is((select count(*) from public.saas_plan_adjustments),0::bigint,'account without operator access cannot read histories');
select throws_ok($$select public.issue_proration_cycle_invoice_pilot(current_setting('qa.proration.issue')::jsonb)$$,'42501',null,'account without operator access cannot issue invoices');
select throws_ok($$select public.rollover_proration_cycle_pilot(current_setting('qa.proration.roll')::jsonb)$$,'42501',null,'account without operator access cannot roll cycles');
select * from finish();
rollback;
